<script>const checks=[...document.querySelectorAll('.recon-check')],all=document.querySelector('#select-all'),total=document.querySelector('#selected-total'),button=document.querySelector('#book-reconciliation');function updateSelection(){const selected=checks.filter(check=>check.checked),amount=selected.reduce((sum,check)=>sum+Number(check.dataset.amount),0);total.textContent=new Intl.NumberFormat().format(amount)+' TZS selected';button.disabled=!selected.length;if(all)all.checked=checks.length>0&&selected.length===checks.length}checks.forEach(check=>check.addEventListener('change',updateSelection));if(all)all.addEventListener('change',()=>{checks.forEach(check=>check.checked=all.checked);updateSelection()});updateSelection();</script>
